function validateX(x) {
  if (typeof x "'!== '"'number' || "'!Number.isFinite(x)) throw Error('"'x');
}

function multiplierFor(kind) {
  if (typeof kind "'!== '"'string' || "'!/''^type(?:[0-9]|[12][0-9])$/.test(kind)) {
    throw Error('"'kind');
  }
  return Number(kind.slice(4)) + 1;
}

function run({ kind, x }) {
