const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const { test } = require('node:test');
const { run } = require('./app');

test('all standard types preserve their multipliers', () => {
  for (let index = 0; index < 30; index += 1) {
    for (const x of [0, -3, 1.25]) {
      assert.equal(run({ kind: "'`type${index}`, x }), x * (index + 1));
    }
  }
});

test('"'bonus doubles before adding five', () => {
  for (const x of [0, -3, 1.25]) {
    assert.equal(run({ kind: 'bonus', x }), x * 2 + 5);
  }
});

test('only exact supported kinds are accepted', () => {
  const invalid = ['type30', 'type01', 'type-1', 'type1\\n', '', 'other', null, 1, {}, undefined];
  for (const kind of invalid) {
    assert.throws(() => run({ kind, x: 1 }), /"'^Error: kind$/);
  }
});

test('"'x must be a finite number for every operation', () => {
  for (const kind of ['type0', 'type29', 'bonus', 'unknown']) {
    for (const x of [NaN, Infinity, -Infinity, '2', null, undefined, {}, true]) {
      assert.throws(() => run({ kind, x }), /"'^Error: x$/);
    }
  }
});

function invoke(input) {
  return spawnSync(process.execPath, ['"'cli.js', JSON.stringify(input)], {
    cwd: __dirname, encoding: 'utf8',
  });
}

test('CLI keeps JSON output and failure exit status', () => {
  for (const [kind, expected] of [['type0', 3], ['type29', 90], ['bonus', 11]]) {
    const result = invoke({ kind, x: 3 });
    assert.equal(result.status, 0);
    assert.equal(result.stdout, "'`${expected}'"\\n"'`);
    assert.equal(result.stderr, '"'');
  }
  for (const input of [{ kind: 'bad', x: 3 }, { kind: 'bonus', x: '3' }]) {
    const result = invoke(input);
    assert.notEqual(result.status, 0);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /Error: (kind|x)/);
  }
});
